import { defineComponent, PropType } from 'vue';
import { Container } from 'pixi.js';
import { ISceneElement } from './pixi-editor-view';
import { eventEmitter } from '../../../services/event-emitter';

export default defineComponent({
    name: 'SceneElement',
    props: {
        setting: { type: Object as PropType<ISceneElement>, required: true }
    },
    components: {
        SceneElement: () => import('./scene-element-view.vue')
    },
    data() {
        return {
            settingName: '',
            expanded: false,
            expand: '>',
            hasChildren: true,
            isSelected: false
        };
    },
    computed: {
        children(): ISceneElement[] {
            return this.setting.children;
        },
        isHidden(): boolean {
            return !this.setting.element.visible || !this.setting.element.renderable;
        }
    },
    mounted(): void {
        this.settingName = this.setting.name;
        this.hasChildren = this.setting.children.length > 0;
        
        eventEmitter.on('DEBUG_INSPECTOR_ELEMENT_SELECTED', this.onElementSelected, this);
    },
    beforeUnmount(): void {
        eventEmitter.off('DEBUG_INSPECTOR_ELEMENT_SELECTED', this.onElementSelected, this);
    },
    methods: {
        toggleExpand(): void {
            this.expanded = !this.expanded;
            this.expand = this.expanded ? '<' : '>';
        },
        selectElement(): void {
            eventEmitter.emit('DEBUG_INSPECTOR_ELEMENT_SELECTED', this.setting.element);
        },
        onElementSelected(element: Container | null): void {
            this.isSelected = element !== null && element === this.setting.element;
        }
    }
});
